\begin{lemma}[Vertex temperatures are positive]
\label{lem:IPhO2026Problems_problem_IPhO_2026_3_C_2:vertex_T_pos}
\lean{IPhO2026.Problem3.C2.CarnotMagnetizationModel.vertex_T_pos}
